293: function IcsImportDialog({ api, calendar, onClose, onAccessDenied, triggerEl }: {
294:   api: ApiClient;
295:   calendar: Calendar;
296:   onClose: () => void;
297:   onAccessDenied: () => void;
298:   triggerEl: HTMLButtonElement | null;
299: }) {
300:   const [file, setFile] = useState<File | null>(null);
301:   const [submitting, setSubmitting] = useState(false);
302:   const [summary, setSummary] = useState<IcsImportSummary | null>(null);
303:   const [error, setError] = useState<string | null>(null);
304:   const closeButton = useRef<HTMLButtonElement>(null);
305: 
306:   useEffect(() => {
307:     closeButton.current?.focus();
308:     return () => { triggerEl?.focus(); };
309:   }, [triggerEl]);
310: 
311:   function close() {
312:     if (!submitting) onClose();
313:   }
314: 
315:   function selectFile(selected: File | undefined) {
316:     setSummary(null);
317:     if (!selected) {
318:       setFile(null);
319:       setError("Choose an ICS file to import.");
320:     } else if (!selected.name.toLowerCase().endsWith(".ics")) {
321:       setFile(null);
322:       setError("Choose a file whose name ends in .ics.");
323:     } else if (selected.size > MAX_ICS_FILE_BYTES) {
324:       setFile(null);
325:       setError("Choose an ICS file that is 1 MiB or smaller.");
326:     } else {
327:       setFile(selected);
328:       setError(null);
329:     }
330:   }
331: 
332:   async function submit(event: FormEvent<HTMLFormElement>) {
333:     event.preventDefault();
334:     if (file === null || submitting) return;
335:     setSubmitting(true);
336:     setError(null);
337:     try {
338:       setSummary(await importIcs(api, calendar.id, file));
339:     } catch (reason) {
340:       if (isCalendarAccessChange(reason)) {
341:         onAccessDenied();
342:         return;
343:       }
344:       if (reason instanceof IcsImportApiError && reason.code === "invalid_calendar_file") {
345:         setError("This file is not a valid supported ICS calendar. Choose a different calendar export.");
346:       } else if (reason instanceof IcsImportApiError && reason.code === "calendar_import_limit_exceeded") {
347:         setError("This calendar exceeds the import limits of 1 MiB or 1,000 events.");
348:       } else {
349:         setError("We could not import this calendar. Please try again.");
350:       }
351:     } finally {
352:       setSubmitting(false);
353:     }
354:   }
355: 
356:   return <div className="ics-import-dialog" role="dialog" aria-modal="true" aria-labelledby="ics-import-heading"
357:     onKeyDown={(event) => { if (event.key === "Escape" && !submitting) { event.preventDefault(); onClose(); } }}>
358:     <div className="ics-import-dialog__card">
359:       <div className="ics-import-dialog__header">
360:         <h3 id="ics-import-heading">Import ICS to {calendar.name ?? "calendar"}</h3>
361:         <button ref={closeButton} className="ics-import-dialog__close" type="button" onClick={close} disabled={submitting} aria-label="Close import">
362:           <span className="material-symbols-outlined" aria-hidden="true">close</span>
363:         </button>
364:       </div>
365:       {summary === null ? <form onSubmit={(event) => void submit(event)}>
366:         <div className="ics-import-dialog__body">
367:           <label className="ics-import-dialog__file-field">ICS file
368:             <input type="file" accept=".ics,text/calendar" disabled={submitting}
369:               onChange={(event) => selectFile(event.currentTarget.files?.[0])} />
370:           </label>
371:           <p className="ics-import-dialog__help">Import one .ics file up to 1 MiB and 1,000 events. Imported events will be editable.</p>
372:           {submitting && <p className="ics-import-dialog__progress" role="status">Importing calendar…</p>}
373:           {error && <p className="ics-import-dialog__error" role="alert">{error}</p>}
374:         </div>
375:         <div className="ics-import-dialog__footer">
376:           <button className="btn-cancel" type="button" onClick={close} disabled={submitting}>Cancel</button>
377:           <button className="btn-primary" type="submit" disabled={file === null || submitting}>{submitting ? "Importing…" : "Import"}</button>
378:         </div>
379:       </form> : <>
380:         <div className="ics-import-dialog__body">
381:           <p className="ics-import-dialog__success" role="status">{summary.imported_events} {summary.imported_events === 1 ? "event" : "events"} imported</p>
382:         </div>
383:         <div className="ics-import-dialog__footer">
384:           <button className="btn-primary" type="button" onClick={onClose}>Done</button>
385:         </div>
386:       </>}
387:     </div>
388:   </div>;
389: }
