445: export function CalendarManagement({ api }: { api: ApiClient }) {
446:   const [calendars, setCalendars] = useState<Calendar[]>([]);
447:   const [loading, setLoading] = useState(true);
448:   const [error, setError] = useState<string | null>(null);
449:   const [editing, setEditing] = useState<Calendar | null | undefined>(undefined);
450:   const [settings, setSettings] = useState<CalendarSettings>(blankSettings);
451:   const [submitting, setSubmitting] = useState(false);
452:   const [sharing, setSharing] = useState<Calendar | null>(null);
453:   const [importing, setImporting] = useState<Calendar | null>(null);
454:   const shareTrigger = useRef<HTMLButtonElement>(null);
455:   const importTrigger = useRef<HTMLButtonElement>(null);
456:   const prevSharingRef = useRef<Calendar | null>(null);
457: 
458:   useEffect(() => {
459:     let active = true;
460:     void (async () => {
461:       try {
462:         const result = await listCalendars(api);
463:         if (active) setCalendars(result);
464:       } catch {
465:         if (active) setError("We could not load your calendars. Please try again.");
466:       } finally {
467:         if (active) setLoading(false);
468:       }
469:     })();
470:     return () => { active = false; };
471:   }, [api]);
472: 
473:   useEffect(() => {
474:     if (prevSharingRef.current !== null && sharing === null) {
475:       prevSharingRef.current = null;
476:       shareTrigger.current?.focus();
477:     }
478:     prevSharingRef.current = sharing;
479:   }, [sharing]);
480: 
481:   function openCreate() { setError(null); setSettings(blankSettings); setEditing(null); }
482:   function openEdit(calendar: Calendar) { setError(null); setSettings(settingsFor(calendar)); setEditing(calendar); }
483:   function replace(calendar: Calendar) { setCalendars((current) => current.map((item) => item.id === calendar.id ? calendar : item)); }
484:   const refreshAfterAccessChange = useCallback(async () => {
485:     setEditing(undefined); setSharing(null); setImporting(null);
486:     try { setCalendars(await listCalendars(api)); }
487:     catch { setCalendars([]); }
488:     setError("Your calendar access changed. The list was refreshed.");
489:   }, [api]);
490: 
491:   async function save(event: FormEvent<HTMLFormElement>) {
492:     event.preventDefault();
493:     setSubmitting(true); setError(null);
494:     const creating = editing === null;
495:     try {
496:       const calendar = creating
497:         ? await createCalendar(api, payload(settings))
498:         : await updateCalendar(api, editing!.id, { ...payload(settings), version: editing!.version! });
499:       setCalendars((current) => creating ? [...current, calendar] : current.map((item) => item.id === calendar.id ? calendar : item));
500:       setEditing(undefined);
501:     } catch (reason) {
502:       if (isCalendarAccessChange(reason)) await refreshAfterAccessChange();
503:       else setError(creating ? "We could not create this calendar." : "We could not save this calendar.");
504:     } finally { setSubmitting(false); }
505:   }
506: 
507:   async function setArchived(calendar: Calendar, archived: boolean) {
508:     setError(null);
509:     try {
510:       const updated = archived ? await archiveCalendar(api, calendar.id) : await restoreCalendar(api, calendar.id);
511:       replace(updated);
512:     } catch (reason) { if (isCalendarAccessChange(reason)) await refreshAfterAccessChange(); else setError(`We could not ${archived ? "archive" : "restore"} this calendar.`); }
513:   }
514: 
515:   async function deleteCalendar(calendar: Calendar) {
516:     setError(null);
517:     try {
518:       await deleteCalendarRequest(api, calendar.id);
519:       setCalendars((current) => current.filter((item) => item.id !== calendar.id));
520:     } catch (reason) { if (isCalendarAccessChange(reason)) await refreshAfterAccessChange(); else setError("We could not delete this calendar."); }
521:   }
522: 
523:   if (loading) return <section aria-busy="true"><p className="calendar-loading" role="status">Loading calendars\u2026</p></section>;
524: 
525:   const activeCalendars = calendars.filter((c) => !c.archived);
526:   const archivedCalendars = calendars.filter((c) => c.archived);
527: 
528:   return <section className="calendar-management" aria-labelledby="calendars-heading">
529:     <header className="calendar-management__header">
530:       <div>
531:         <h2 id="calendars-heading">Calendars</h2>
532:         <p>Manage your calendars, sharing settings, and default behaviors.</p>
533:       </div>
534:       <button className="calendar-management__new-btn" type="button" onClick={openCreate}>
535:         <span className="material-symbols-outlined">add</span>
536:         New calendar
537:       </button>
538:     </header>
539: 
540:     {error && <p className="app-message app-message--error" role="alert">{error}</p>}
541: 
542:     {editing !== undefined && <CalendarFormModal editing={editing} settings={settings} setSettings={setSettings} onSave={save} onCancel={() => setEditing(undefined)} submitting={submitting} />}
543: 
544:     {activeCalendars.length > 0 && <h3 className="calendar-section-title">Active Calendars</h3>}
545:     <div className="calendar-grid">
546:       {activeCalendars.map((calendar) => <CalendarCard key={calendar.id} calendar={calendar}
547:         onEdit={() => openEdit(calendar)}
548:         onShare={() => { setSharing(calendar); }}
549:         onImport={() => { setImporting(calendar); }}
550:         onArchive={() => void setArchived(calendar, true)}
551:         shareTriggerRef={shareTrigger}
552:         importTriggerRef={importTrigger}
553:       />)}
554:     </div>
555: 
556:     {archivedCalendars.length > 0 && <h3 className="calendar-section-title">Archived Calendars</h3>}
557:     <div className="calendar-grid">
558:       {archivedCalendars.map((calendar) => <CalendarCard key={calendar.id} calendar={calendar}
559:         onEdit={() => openEdit(calendar)}
560:         onShare={() => { setSharing(calendar); }}
561:         onImport={() => { setImporting(calendar); }}
562:         onArchive={() => void setArchived(calendar, false)}
563:         shareTriggerRef={shareTrigger}
564:         importTriggerRef={importTrigger}
565:         onDelete={() => void deleteCalendar(calendar)}
566:       />)}
567:     </div>
568: 
569:     {calendars.length === 0 && <div className="calendar-empty">
570:       <div className="calendar-empty__icon"><span className="material-symbols-outlined">calendar_month</span></div>
571:       <h3>No calendars yet.</h3>
572:       <p>Create your first calendar to start managing events.</p>
573:       <button className="calendar-management__new-btn" type="button" onClick={openCreate} aria-label="Create your first calendar">
574:         <span className="material-symbols-outlined">add</span>
575:         New calendar
576:       </button>
577:     </div>}
578: 
579:     {sharing && <SharingDialog api={api} calendar={sharing} onClose={() => setSharing(null)} onCalendarChanged={(calendar) => { replace(calendar); setSharing(calendar); }} onAccessDenied={() => { void refreshAfterAccessChange(); }} triggerEl={shareTrigger.current} />}
580:     {importing && <IcsImportDialog api={api} calendar={importing} onClose={() => setImporting(null)} onAccessDenied={() => { void refreshAfterAccessChange(); }} triggerEl={importTrigger.current} />}
581:   </section>;
582: }

